{
  "name": "SCILA抽屉式培养存储装置",
  "name_en": "SCILA drawer-based incubation/storage unit",
  "manufacturer": "INHECO",
  "description": "一种带抽屉访问的实验室环境控制装置，可用于样品或微孔板的培养或受控存储。该设备支持温度控制，并可查询液位、温度、CO₂流量、阀门以及抽屉状态。",
  "description_en": "A drawer-based laboratory environmental control unit for incubating or storing samples or microplates under controlled conditions. It supports temperature control and can report liquid level, temperature, CO2 flow, valve status, and drawer status.",
  "actions": [
    {
      "action_name": "auto-request_status",
      "description": "获取设备总体状态。",
      "description_en": "Get the overall device status."
    },
    {
      "action_name": "auto-request_liquid_level",
      "description": "获取液位信息。",
      "description_en": "Get the liquid level information."
    },
    {
      "action_name": "auto-request_temperature_information",
      "description": "获取温度信息。",
      "description_en": "Get temperature information."
    },
    {
      "action_name": "auto-measure_temperature",
      "description": "测量当前温度。",
      "description_en": "Measure the current temperature."
    },
    {
      "action_name": "auto-request_target_temperature",
      "description": "获取目标温度。",
      "description_en": "Get the target temperature."
    },
    {
      "action_name": "auto-is_temperature_control_enabled",
      "description": "查询温度控制是否已启用。",
      "description_en": "Check whether temperature control is enabled."
    },
    {
      "action_name": "auto-request_drawer_statuses",
      "description": "获取所有抽屉状态。",
      "description_en": "Get the status of all drawers."
    },
    {
      "action_name": "auto-request_drawer_status",
      "description": "获取指定抽屉状态。",
      "description_en": "Get the status of a specified drawer."
    },
    {
      "action_name": "auto-request_co2_flow_status",
      "description": "获取CO₂流量状态。",
      "description_en": "Get the CO2 flow status."
    },
    {
      "action_name": "auto-request_valve_status",
      "description": "获取阀门状态。",
      "description_en": "Get the valve status."
    },
    {
      "action_name": "auto-start_temperature_control",
      "description": "启动温度控制并设定目标温度。",
      "description_en": "Start temperature control and set the target temperature."
    },
    {
      "action_name": "auto-stop_temperature_control",
      "description": "停止温度控制。",
      "description_en": "Stop temperature control."
    },
    {
      "action_name": "auto-serialize",
      "description": "序列化设备配置或状态数据。",
      "description_en": "Serialize the device configuration or state data."
    },
    {
      "action_name": "auto-deserialize",
      "description": "从序列化数据恢复设备配置或状态。",
      "description_en": "Restore the device configuration or state from serialized data."
    }
  ],
  "tag_hints": [
    "temperature-controlled incubation",
    "drawer-based storage",
    "CO2 control",
    "humidification reservoir",
    "liquid level monitoring",
    "microplate incubation",
    "environmental chamber"
  ]
}

